import{z as D,x as c,o,c as E,q as r,j as n,D as a,d as l,s as i,S as s}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"TorchTitan","description":"","frontmatter":{"title":"TorchTitan","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/torchtitan.md","filePath":"llm/torchtitan.md","lastUpdated":1791063341000}'),p={name:"llm/torchtitan.md"};function B(P,e,d,h,m,T){const t=c("Mermaid");return o(),E("div",null,[e[2]||(e[2]=r('<h1 id="torchtitan" tabindex="-1">TorchTitan <a class="header-anchor" href="#torchtitan" aria-label="Permalink to &quot;TorchTitan&quot;">​</a></h1><div class="epigraph"><p>并行不该散落在互不兼容的第三方运行时里：把切分写成 DTensor 在 DeviceMesh 上的属性，4D 才能和 torch.compile、Float8、分布式检查点叠在同一份 PyTorch 原生作业里。</p><footer>—— Liang et al., TorchTitan: One-stop PyTorch native solution for production ready LLM pretraining, arXiv:2410.06511</footer></div><p>预训练到 Llama 3.1 405B 量级，要把数据并行、张量并行、流水线、上下文并行与检查点、混合精度叠在一起。现成栈往往各管一段：Megatron 管 TP/PP，DeepSpeed 管 ZeRO，编译器与 FP8 核又在第三个仓库，组合作业的工程税很高。<strong>TorchTitan</strong>（Meta PyTorch 团队，代码 <code>pytorch/torchtitan</code>）的主张是：<strong>PyTorch 原生</strong>的一站式预训练系统——用 Distributed Tensor（DTensor）与 DeviceMesh 做可组合的 4D 并行，接 <a href="/llm/fsdp">FSDP2</a>、<code>torch.compile</code>、Float8、SymmetricMemory，并给出 Llama 3.1 家族在 H100 上的配方。本篇按 2410.06511 写组合方式与公开加速比，不把某一版 nightly 的未定 API 当规范，也不编造未写入论文的 16K 卡作业数字。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>论文把现有分布式系统的缺口写成几条：并行技术难以叠加；架构不模块，新硬件和新切分进不去；没有吃到编译器与新数值格式；生产上的分布式检查点、故障恢复与调试工具不足；依赖外部、维护不同步的库，反而用不上 PyTorch 自己的核。根因是缺少贯穿全栈的<strong>统一张量与设备抽象</strong>：没有它，并行、检查点与优化仍然碎片化。</p><p>TorchTitan 的研究贡献被作者写成：把并行与优化的原则收成一套模板，扩展 DTensor 的 n 维切分，使其与 <code>torch.compile</code>、state dict 检查点兼容，并在 Llama 3.1 8B–405B 上从 8 卡扫到 512 卡，验证弹性扩展。它是完整训练系统，而不是技术清单。</p><h3 id="原生-dtensor-把切分写成张量属性" tabindex="-1">原生 DTensor 把切分写成张量属性 <a class="header-anchor" href="#原生-dtensor-把切分写成张量属性" aria-label="Permalink to &quot;原生 DTensor 把切分写成张量属性&quot;">​</a></h3><p>DeviceMesh 声明网格轴：例如数据并行轴、张量并行轴、流水线轴、上下文轴。DTensor 是逻辑上完整、物理上分片的张量，单设备语义保持不变。FSDP2 的 <code>fully_shard</code> 把参数切在 DP 轴上；TP 用列/行切的 placement 作用在同一张 DTensor 上；二者组合不再经过「先包 Megatron 层再包 ZeRO 引擎」的双重运行时。HSDP 在节点内深切、节点间复制，对应 <code>data_parallel_replicate_degree</code> 与 <code>data_parallel_shard_degree</code> 同时大于 1——以仓库配置名为准。</p><p>每个模型提供 <code>parallelize_*</code>：按固定顺序套 TP、激活检查点、compile、FSDP 包装，避免维之间的非法组合。流水线用 <code>pipeline_module_split</code> 把模块切到 PP mesh 的各段。上下文并行沿序列切，使长上下文的激活能放下。顺序很重要：先 TP 再 FSDP 与先 FSDP 再 TP 的通信形状不同，论文把「可组合」定义成有文档的顺序，而不是任意排列。</p><p><span class="marginnote">FSDP2 相对 FSDP1：composable API、DTensor 布局、可以配置前向后是否立即 reshard。调试时不要假设 <code>named_parameters()</code> 指向未切分权重；应用 <code>summon</code> 一类 API 查看完整参数。</span></p><p><span class="marginnote">「DTensor」可以理解成一张逻辑上完整、物理上切碎的张量：你的代码仍像在单卡上写矩阵乘，框架根据它携带的切分信息（哪个维度切了几份、存在哪些卡上）自动插入集合通信。类比一份共享文档：每人只编辑自己那一节，系统负责同步别人的改动，你看到的是整篇。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>4D = DP（含 FSDP2 / HSDP）+ TP + PP + CP。论文在 Llama 3.1 上给出从 1D 到 4D 的配方：小模型可以只开 FSDP（1D）；70B 进入 2D（FSDP+TP）；405B 进入 3D（再加 PP）；长上下文再加 CP 成 4D。这是作者在 H100 上的经验曲线，不是定理：以太网机房可能更早需要 PP，NVSwitch 域更大则 TP 可以更宽。</p><p>硬件协同：Float8 训练把 GEMM 收到 FP8；SymmetricMemory 用来做对称内存上的通信优化（文档中的异步 TP 等）。激活检查点可调粒度，在内存与重计算之间走。<code>torch.compile</code> 作用在已切分的图上，论文强调他们为 DTensor+compile 修过关键缺陷，否则切分与编译器互相踩。分布式检查点走 PyTorch DCP，按 DTensor 的 state dict 存，故障恢复不必先聚合到单机。Flight Recorder 一类工具用来查卡住的集合通信。</p>',14)),(o(),n(s,null,{default:a(()=>[i(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20MESH%5B%22DeviceMesh%20%E8%BD%B4%3A%20DP%20TP%20PP%20CP%22%5D%20--%3E%20DT%5B%22DTensor%20%E5%8F%82%E6%95%B0%22%5D%0A%20%20DT%20--%3E%20FSDP%5B%22FSDP2%20%2F%20HSDP%22%5D%0A%20%20DT%20--%3E%20TP%5B%22%E5%BC%A0%E9%87%8F%E5%B9%B6%E8%A1%8C%20placement%22%5D%0A%20%20DT%20--%3E%20PP%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%E5%88%86%E6%AE%B5%22%5D%0A%20%20DT%20--%3E%20CP%5B%22%E4%B8%8A%E4%B8%8B%E6%96%87%20%2F%20%E5%BA%8F%E5%88%97%E5%88%87%22%5D%0A%20%20FSDP%20--%3E%20COMP%5B%22torch.compile%20%C2%B7%20Float8%22%5D%0A%20%20TP%20--%3E%20COMP%0A%20%20COMP%20--%3E%20CKPT%5B%22DCP%20%E5%88%86%E7%89%87%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r('<h3 id="_4d-与-llama-3-1-配方" tabindex="-1">4D 与 Llama 3.1 配方 <a class="header-anchor" href="#_4d-与-llama-3-1-配方" aria-label="Permalink to &quot;4D 与 Llama 3.1 配方&quot;">​</a></h3><p>论文报告：在优化过的基线上，堆叠训练优化后，Llama 3.1 <strong>8B / 128 GPU / 1D</strong> 加速约 <strong>65.08%</strong>；<strong>70B / 256 GPU / 2D</strong> 约 <strong>12.59%</strong>；<strong>405B / 512 GPU / 3D</strong> 约 <strong>30%</strong>。GPU 为 NVIDIA H100。4D 被用来展示长上下文可训，而不是再报一条更大的百分比。这些数字是相对<strong>作者的优化基线</strong>的墙钟改善，不是相对随机 Megatron 脚本的 MFU 对比，也不能外推到 A100 或别的模型族。Llama 3.1 405B 原文训练用了远大于 512 的集群；TorchTitan 论文演示的是系统在 512 卡 3D 下仍能高效，不是复现 16K 卡预训练。</p><p><span class="marginnote">65% 出现在 8B、1D、128 卡，因为基线在小模型上更容易被 compile/Float8 拉开；70B 的 12.59% 更小，说明 2D 时通信与内核已经更接近屋顶。读百分比时必须带模型、卡数与维数。</span></p><p><span class="marginnote">数字直觉：70B 参数用 bf16 存，一份完整权重要约 140 GB，单张 80 GB 的 H100 根本放不下，所以 70B 起步就得 2D（FSDP+TP）把权重切到多卡；405B 更是约 810 GB，必须 3D 起步。「从几维开始」首先是显存算术，其次才是吞吐优化。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>可组合的关键是：每一种并行只改 DTensor 的 placement 或模块到 mesh 的映射，集体通信由 DTensor 原语发出，而不是各库各写一套 NCCL wrapper。FSDP 的 All-Gather 与 TP 的 All-Reduce 作用在不同 mesh 维上，只要维正交，语义就是 Kronecker 式的网格。PP 不切单层矩阵，只切深度，与 TP 正交；微批填气泡。CP 切序列，注意力跨段通信，与 batch 维的 DP 正交。非法组合（例如在 PP 段之间再做需要全层权重的操作却忘记聚集）会在单设备语义上失败——这正是「保持单设备语义」这条不变量的用处。</p><p>弹性扩展：改 mesh 形状等于改作业，检查点必须能按新 placement 加载。论文把这当成生产性质，而不是研究原型。Float8 与 compile 改的是核与通信融合，不改 4D 的数学切分。</p>',7)),(o(),n(s,null,{default:a(()=>[i(t,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%80%E6%AC%A1%E5%89%8D%E5%90%91%E9%87%8C%E7%9A%84%E4%B8%89%E7%B1%BB%E9%80%9A%E4%BF%A1%22%5D%20--%3E%20A%5B%22FSDP%20All-Gather%EF%BC%9A%E8%B5%B0%20DP%20%E8%BD%B4%22%5D%0A%20%20Q%20--%3E%20B%5B%22TP%20All-Reduce%EF%BC%9A%E8%B5%B0%20TP%20%E8%BD%B4%22%5D%0A%20%20Q%20--%3E%20C%5B%22CP%20%E6%B3%A8%E6%84%8F%E5%8A%9B%E8%B7%A8%E6%AE%B5%EF%BC%9A%E8%B5%B0%E5%BA%8F%E5%88%97%E8%BD%B4%22%5D%0A%20%20A%20--%3E%20D%5B%22%E5%90%84%E8%B5%B0%E5%90%84%E7%9A%84%20mesh%20%E7%BB%B4%EF%BC%8C%E4%BA%92%E4%B8%8D%E6%8C%A4%E5%8D%A0%22%5D%0A%20%20B%20--%3E%20D%0A%20%20C%20--%3E%20D%0A%20%20D%20--%3E%20E%7B%22%E5%8D%95%E8%AE%BE%E5%A4%87%E8%AF%AD%E4%B9%89%E8%BF%98%E6%88%90%E7%AB%8B%E5%90%97%EF%BC%9F%22%7D%0A%20%20E%20--%3E%7C%22%E6%88%90%E7%AB%8B%22%7C%20OK%5B%22%E7%BB%84%E5%90%88%E5%90%88%E6%B3%95%EF%BC%8C%E7%BB%A7%E7%BB%AD%E8%AE%AD%E7%BB%83%22%5D%0A%20%20E%20--%3E%7C%22%E5%BF%98%E8%81%9A%E9%9B%86%E5%85%A8%E5%B1%82%E6%9D%83%E9%87%8D%22%7C%20BAD%5B%22%E6%8A%A5%E9%94%99%E6%88%96%E6%95%B0%E5%80%BC%E9%94%99%E8%AF%AF%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<h3 id="相对-megatron-deepspeed-的位置" tabindex="-1">相对 Megatron / DeepSpeed 的位置 <a class="header-anchor" href="#相对-megatron-deepspeed-的位置" aria-label="Permalink to &quot;相对 Megatron / DeepSpeed 的位置&quot;">​</a></h3><p><a href="/llm/megatron-core">Megatron-Core</a> 同样可组合，但是 NVIDIA 积木 + Transformer Engine，模型往往要写成 Core 模块。<a href="/llm/zero-stages">DeepSpeed</a> 用 JSON 档位与引擎包装模块。TorchTitan 赌的是：你愿意跟 PyTorch 2.x API（FSDP2、DTensor、compile），用较少的外部运行时换可维护性。它不是「更快所以替代 Megatron」；405B 配方仍可能在 Core 里有更熟的 MoE 路径。仓库后来加的 DeepSeek-V3、Qwen3 等 <code>parallelize_*</code>，以当时代码为准，不要全部算进 2410.06511 的实验表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 65% / 12.59% / 30% 写成对任意基线的承诺。不要在 FSDP1 包装下假设 DTensor 配方能直接跑。不要把 SymmetricMemory、异步 TP 当成所有硬件上都已默认打开。检查点格式与 Megatron / Hugging Face 之间需要转换，不是改扩展名。论文评估在 H100；换互联带宽，4D 的最优维数会动。</p><p>生产还依赖数据加载、tokenizer、容错重启策略；Titan 提供日志与 DCP，但不包含你的业务调度器。MoE 的 expert parallel 在后续仓库演进中出现，引用时写清论文版（Llama 稠密 3.1）与代码版。</p><p><span class="marginnote">常见误区：把「加速 65.08%」读成「比 Megatron 快 65%」。论文测的是相对作者自己优化过的基线（已开 compile、Float8 等优化）的墙钟改善；换个基线实现、换成 A100、换个模型族，这个数字都不成立。</span></p><p><span class="marginnote">出处：Liang、Liu 等 <em>TorchTitan</em>，arXiv:2410.06511；代码 github.com/pytorch/torchtitan。FSDP 见 PyTorch 文档。Llama 3.1 规模数字来自 Dubey 等，用来说明预训练需求，不是 Titan 论文自己训了 16K 卡。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TorchTitan 是 PyTorch 原生的 LLM 预训练系统：DeviceMesh + DTensor 上组合 4D 并行。</li><li>与 compile、Float8、DCP、FSDP2 同一栈；Llama 3.1 8B/70B/405B 在 H100 上报告 65.08% / 12.59% / 30% 相对优化基线的加速。</li><li>位置是原生可维护模板，不是自动替代 Megatron-Core 或 DeepSpeed。</li><li>出处：arXiv:2410.06511。</li></ul>',9))])}const F=D(p,[["render",B]]);export{g as __pageData,F as default};
